'use strict';
// Original educational exercises. Not a replica of, or connection to, Google Ads.
const SETUP_STEPS=[
{id:'outcome',title:P('01 · Result aur customer','01 · Outcome and customer'),where:'Before account setup',source:['setup'],screen:1,
do:P('Ek customer, ek offer aur ek business result choose karo. Campaign ka naam reporting mein useful ho: business, service, location aur intent. Objective choose karna aur conversion action select karna do alag decisions hain.','Choose a customer, an offer and a business outcome. Use a campaign name that identifies service, location and intent. Selecting an objective and selecting the conversion action are separate decisions.'),
trap:P('Sirf website traffic ko revenue ki proof samajhna.','Treating website traffic as proof of revenue.'),output:P('Customer + offer + success ki definition likho.','Write the customer, offer and definition of success.'),q:P('Sab se useful starting brief kaunsa hai?','Which is the most useful starting brief?'),options:[P('Zyada se zyada clicks chahiye','Get as many clicks as possible'),P('Defined service/product ke liye relevant customer aur measurable business outcome','A relevant customer and measurable outcome for a defined offer'),P('Competitor ki har setting copy karni hai','Copy every competitor setting')],answer:1,why:P('Clear outcome se keywords, page, tracking aur bidding ko ek direction milti hai.','A clear outcome connects keywords, the page, tracking and bidding.')},
{id:'measurement',title:P('02 · Conversion signal test','02 · Test the conversion signal'),where:'Goals → Conversions → Summary',source:['goals','webconversions','tagtest'],screen:3,
do:P('Action ka source, selected goal, counting, value/currency aur primary/secondary role record karo. Valid completion, invalid submission aur repeat test karo. Sales/CRM se reconcile karo; GA4 import aur Ads tag se ek outcome double count na ho. Custom goals mein secondary action bhi bidding mein use ho sakta hai.','Record source, selected goal, counting, value/currency and primary/secondary role. Test success, invalid submission and repetition. Reconcile with sales/CRM and check duplicate measurement through GA4 and Ads tags. A secondary action in a custom goal can still be used for bidding.'),
trap:P('Button click ko successful form ya paid purchase count karna.','Counting a button click as a successful form or paid purchase.'),output:P('Event, source, primary/secondary role, count rule aur 3 test results likho.','Write the event, source, primary/secondary role, count rule and three test results.'),q:P('Form error par bhi conversion fire hoti hai. Pehle kya karna hai?','A conversion fires even when the form fails. What comes first?'),options:[P('Budget double karo','Double the budget'),P('Isay successful lead maan lo','Accept it as a successful lead'),P('Success-only trigger fix karke valid/invalid/repeat dobara test karo','Fix the success-only trigger and repeat valid/invalid/repeat tests')],answer:2,why:P('Ghalat signal par optimization sahi customers seekhnay ki bajaye errors ko reward kar sakti hai.','A bad signal can reward errors instead of meaningful customer outcomes.'),practice:'tracking'},
{id:'economics',title:P('03 · Pehle numbers samjho','03 · Understand the economics'),where:'Business records → contribution → acquisition limit',source:['measurement'],
do:P('Revenue mein se variable delivery/product costs nikal kar contribution samjho. Raw lead se customer banne ki rate alag rakho. Neechay fictional numbers se break-even limit nikaalo; operating profit ke liye target is limit se neeche chahiye. Repeat value bina evidence assume mat karo.','Understand contribution after variable product/delivery costs. Keep the raw-lead-to-customer rate separate. Calculate the break-even limit below using fictional inputs; a profitable operating target must be lower. Do not assume repeat value without evidence.'),
trap:P('Revenue ko poora profit samajh kar target CPA set karna.','Setting target CPA as if all revenue were profit.'),output:P('Target acquisition cost, margin assumption aur test loss limit record karo.','Record target acquisition cost, margin assumption and the test loss limit.'),q:P('Lead ki affordable cost kis se connect hoti hai?','What connects to an affordable lead cost?'),options:[P('Customer contribution × lead-to-customer probability','Customer contribution × lead-to-customer probability'),P('Sirf competitor ka CPC','Only competitor CPC'),P('Sirf ad strength','Only Ad Strength')],answer:0,why:P('Har lead sale nahi. Expected contribution per lead mein close rate include hoti hai. Ye sample model fixed overhead aur profit reserve exclude karta hai.','Not every lead becomes a sale. Expected contribution per lead includes the close rate. This sample model excludes fixed overhead and a profit reserve.')},
{id:'campaign',title:P('04 · Objective, Search aur goals','04 · Objective, Search and goals'),where:'Create → Campaign → Objective → Search → Goals',source:['setup','tracking'],screen:2,
do:P('Business objective select karo, Search type confirm karo aur selected conversion goals ka review karo. Imported/default goals automatically sahi assume mat karo. Meaningful campaign name do. Flow ki order account ke mutabiq change ho sakti hai; live wizard draft automatically save bhi kar sakta hai.','Select the business objective, confirm Search and review the selected conversion goals. Do not assume imported/default goals are appropriate. Name the campaign meaningfully. Account workflows can differ and the real wizard can autosave a draft.'),
trap:P('Search chahiye lekin default recommendation se doosra campaign type choose ho jana.','Accepting another campaign type when the intended plan is Search.'),output:P('Campaign name, objective, Search type aur selected goal likho.','Write the campaign name, objective, Search type and selected goal.'),q:P('Account default mein newsletter aur purchase dono hain. Shop ko sales chahiye.','Account defaults include newsletter and purchase. The shop wants sales.'),options:[P('Dono ko automatically equal sales samjho','Automatically treat both as equivalent sales'),P('Selected goals/actions review karo aur sales result ke mutabiq align karo','Review the selected goals/actions and align them with sales'),P('Tracking ko ignore karo','Ignore measurement')],answer:1,why:P('Goal selection bidding signal badal sakti hai. Custom/default goal behavior samajh kar choose karo.','Goal selection can change the bidding signal. Review how default and custom goals behave.')},
{id:'targeting',title:P('05 · Kahan, kis ko, kab','05 · Where, who and when'),where:'Campaign settings → Networks / Locations / Languages / Audiences / Schedule',source:['geo','settings'],
do:P('Included/excluded areas aur location option inspect karo. Physical local service ke liye area mein maujood customers ki need dekho; overseas buyer ka case alag hai. Supported languages, timezone, staffed call hours aur mobile experience align karo. Search partners ko separate test decision samjho. Observation reach restrict nahi karta; Targeting karta hai.','Inspect included/excluded areas and location options. Local physical services and overseas buyers can need different location relationships. Align supported languages, timezone, staffed call hours and mobile experience. Treat Search partners as a separate test decision. Observation does not restrict reach; Targeting does.'),
trap:P('Sirf city naam dekh kar location option aur service hours skip karna.','Checking the city name while skipping location options and operating hours.'),output:P('Areas/exclusions, location option, languages, network decision, timezone, schedule aur audience mode likho.','Write areas/exclusions, location option, languages, network decision, timezone, schedule and audience mode.'),q:P('Sirf Lahore mein onsite repair hoti hai. Ad overseas interest se enquiries la rahi hai.','Onsite repairs are only available in Lahore. Overseas interest is generating enquiries.'),options:[P('Har lead ke liye countrywide service claim karo','Claim nationwide service for every lead'),P('Keywords sab delete karo','Delete all keywords'),P('Actual location report, location option aur page ki coverage verify karo','Verify location reporting, the location option and page coverage')],answer:2,why:P('Location signals perfect boundary nahi. Reports aur real lead areas dono se mismatch investigate karo.','Location signals are not a perfect boundary. Investigate using both reports and actual lead locations.')},
{id:'structure',title:P('06 · Intent se ad group banao','06 · Build ad groups around intent'),where:'Campaign → Ad groups → relevant landing pages',source:['setup'],
do:P('Budget/control ki zarurat par campaign split karo; closely related intent ko ad group mein rakho. Brand aur non-brand ko report mein pehchan sako. Service, product aur research intent ko sirf same lafz ki wajah se mix mat karo. Har keyword ke liye alag group banana universal rule nahi.','Split campaigns when budget or control needs justify it. Group closely related intent into ad groups. Distinguish brand and non-brand in reporting. Shared words do not justify mixing service, product and research intent. A separate group for every keyword is not a universal rule.'),
trap:P('Ek ad group mein repair booking, jobs aur training ka mixed offer.','Mixing repair booking, jobs and training in one offer.'),output:P('Ek campaign ke 2 focused ad groups aur unke pages map karo.','Map two focused ad groups and their landing pages.'),q:P('Service aur installation ke alag pages/offers hain.','Service and installation have different offers/pages.'),options:[P('Intent ke mutabiq relevant groups aur pages map karo','Map relevant groups and pages to intent'),P('Sab ko homepage par bhejo; relevance zaroori nahi','Send everything to the homepage; relevance is irrelevant'),P('Random groups banao','Create random groups')],answer:0,why:P('Useful structure ka maqsad customer ki need, message aur page ko connect karna hai.','Useful structure connects customer need, the message and the page.')},
{id:'keywords',title:P('07 · Keywords aur match types','07 · Keywords and match types'),where:'Keyword Planner / Ad group → Keywords',source:['match'],
do:P('Business se seed terms lo, Planner mein location/language context ke saath ideas aur forecasts dekho. Numbers estimates hain. [Exact] meaning/intent ke close variants match kar sakta hai; "phrase" meaning par bhi depend karta hai; broad wider related intent tak ja sakta hai. Query ka exact string match guarantee nahi. Match choice ko bidding, measurement aur review capacity se joro.','Use business seed terms and review Planner ideas/forecasts in location and language context. Estimates are not guarantees. [Exact] can include close meaning/intent variants; "phrase" also considers meaning; broad can reach more related intent. Exact-string matching is not guaranteed. Connect match choice to bidding, measurement and review capacity.'),
trap:P('Exact match ka matlab sirf bilkul wohi typed words samajhna.','Assuming exact match means only the identical typed words.'),output:P('5 relevant keywords, match types, intent aur matching page likho.','Write five relevant keywords, match types, intent and matching page.'),q:P('[ac repair lahore] select hai. Kya sirf wohi exact typed phrase match hogi?','With [ac repair lahore], is only that identical typed phrase eligible?'),options:[P('Haan, hamesha sirf wohi words','Yes, always only those words'),P('Nahi, close variants aur same meaning/intent bhi eligible ho saktay hain','No, close variants and the same meaning/intent can be eligible'),P('Is se Display campaign ban jati hai','It becomes a Display campaign')],answer:1,why:P('Keyword aur actual search term alag cheezen hain. Real search-term evidence ko regularly review karo.','The keyword and actual search term are different. Review actual search-term evidence regularly.'),practice:'keywords'},
{id:'negatives',title:P('08 · Negatives aur conflicts','08 · Negatives and conflicts'),where:'Search terms → review → negative keyword scope',source:['negative','terms'],
do:P('Irrelevant intent ki list banao, phir account/campaign/ad-group scope socho. Negative broad/phrase/exact ki rules positive match se different hain; close variants automatically cover nahi hotay. Broad negative mein sab terms kisi bhi order mein hon to blocking ho sakti hai. Phrase order aur exact query boundaries alag hain. Conflicts aur singular/plural variants review karo.','List irrelevant intent and choose account/campaign/ad-group scope. Negative broad/phrase/exact follow different rules from positive matching; close variants are not automatically covered. Broad negatives can block when all terms occur in any order. Phrase order and exact-query boundaries differ. Review conflicts and singular/plural variants.'),
trap:P('Shoe store mein "free shipping" useful hai lekin free ko account negative bana dena.','Adding free as an account negative when free shipping is relevant to the shop.'),output:P('3 negative candidates, unka scope/match aur ek useful-query conflict test likho.','Write three negative candidates, scope/match type and one useful-query conflict test.'),q:P('Useful query "buy shoes free delivery" hai. Account negative free se kya risk hai?','A useful query is "buy shoes free delivery". What is the risk of an account negative free?'),options:[P('Har sale guaranteed barhay gi','Every sale is guaranteed to rise'),P('Koi useful query kabhi block nahi hoti','Useful queries can never be blocked'),P('Relevant traffic block ho sakti hai; narrower negative intent aur scope review karo','Relevant traffic may be blocked; review narrower intent and scope')],answer:2,why:P('Negative ka kaam unwanted intent remove karna hai. Useful demand ko accidentally remove karna cost bachanay ki proof nahi.','Negatives remove unwanted intent. Accidentally removing useful demand is not proof of an improvement.')},
{id:'rsa',title:P('09 · Responsive Search Ad','09 · Responsive Search Ad'),where:'Ad group → Ads → Responsive search ad',source:['rsa'],
do:P('RSA mein 3–15 headlines (30 characters tak), 2–4 descriptions (90 tak) aur optional display paths (15 tak har field) hotay hain. Actual destination final URL hai; path sirf display hai. Unique, truthful, relevant messages likho. Har text combination samajh aaye. Pinning ki specific zarurat ho to use karo; Ad Strength business profit ya approval ki guarantee nahi.','An RSA accepts 3–15 headlines (up to 30 characters each), 2–4 descriptions (up to 90) and optional display paths (up to 15 each). The final URL determines the destination. Write distinct, truthful messages that work together. Use pinning for a specific requirement; Ad Strength does not guarantee profit or approval.'),
trap:P('Unsupported "No.1" claim, fake discount ya unavailable same-day promise.','Unsupported "No.1" claims, fake discounts or unavailable same-day promises.'),output:P('3 distinct headlines, 2 descriptions aur final page ka promise likho.','Write three distinct headlines, two descriptions and the final page’s promise.'),q:P('Kaunsa draft review sab se useful hai?','Which draft review is most useful?'),options:[P('Har headline truthful ho, combinations meaningful hon aur page offer deliver kare','Truthful headlines, meaningful combinations and a page that delivers the offer'),P('Bas repeated keywords bhar do','Just repeat keywords everywhere'),P('Excellent score ko Google approval samjho','Treat an Excellent score as Google approval')],answer:0,why:P('Serving combinations aur truncation vary kar saktay hain. Essential message ko unsupported assumptions par mat chhoro.','Serving combinations and truncation can vary. Do not rely on unsupported assumptions for essential messaging.'),practice:'ad'},
{id:'page',title:P('10 · Landing page aur assets','10 · Landing page and assets'),where:'Final URL → mobile test / campaign assets',source:['creative','setup'],
do:P('Mobile par page kholo: correct product/service, price/terms, stock, service area, trust/contact, clear CTA aur working form/checkout inspect karo. Sitelinks relevant pages par; call assets staffed hours ke mutabiq; callouts aur snippets factual. Destination, redirects aur URL parameters test karo. Consent aur privacy requirements implementation mein review karo.','Open the page on mobile: inspect the offer, price/terms, stock, coverage, trust/contact, clear CTA and working form/checkout. Use relevant sitelinks, staffed call assets and factual callouts/snippets. Test redirects and URL parameters. Review applicable consent and privacy requirements in implementation.'),
trap:P('Ad mein running shoes, destination par sold-out sandals.','Advertising running shoes while sending users to sold-out sandals.'),output:P('Final page, mobile success test, relevant assets aur promise evidence likho.','Write the final page, mobile success test, relevant assets and evidence for the promise.'),q:P('Clicks aa rahay hain lekin mobile checkout fail hota hai.','Clicks arrive but mobile checkout fails.'),options:[P('Bid increase karo','Increase bids'),P('Checkout fix aur end-to-end retest ko priority do','Prioritize the checkout fix and end-to-end retest'),P('Page ko ignore karke ad text change karo','Ignore the page and change ad text')],answer:1,why:P('Broken customer journey ko extra traffic bhejnay se meaningful results improve honay ki guarantee nahi.','Sending more traffic to a broken customer journey does not reliably improve business outcomes.')},
{id:'bidding',title:P('11 · Bidding aur AI ka faisla','11 · Bidding and AI decisions'),where:'Bidding → goal / target / AI Max controls',source:['bid','bidlabels','bidtargets','ai','aicontrol'],
do:P('Goal conversions hai ya value? Measurement quality, business economics aur data context se strategy choose karo. Count-based aur value-based optimization alag hain. CPA/ROAS target ko observed mature results aur affordable economics se justify karo; universal magic target nahi. AI Max ke matching, text customization aur URL expansion controls/destinations ko separately review karo.','Choose whether the goal is conversion count or value. Consider measurement quality, economics and data context. Count-based and value-based optimization differ. Justify CPA/ROAS targets using mature results and affordable economics. Review AI Max matching, text customization and URL expansion controls/destinations separately.'),
trap:P('AI ko broken tracking aur irrelevant landing pages fix karne ka substitute samajhna.','Expecting AI to replace correct tracking and relevant destinations.'),output:P('Bidding objective, target ki reason, AI/URL expansion choices aur monitoring plan likho.','Write the bidding objective, target rationale, AI/URL expansion choices and monitoring plan.'),q:P('Sab purchases ko same dummy value di gayi hai, margins alag hain.','Every purchase has the same dummy value although margins differ.'),options:[P('Extremely high ROAS target se value automatically correct ho gi','An extremely high ROAS target will fix the values'),P('Har click ko revenue count karo','Count every click as revenue'),P('Value signal aur business model correct karo, phir value-based strategy assess karo','Correct the value signal/model before assessing a value-based strategy')],answer:2,why:P('Algorithm wahi values seekhta hai jo tum bhejtay ho. Target business reality ka substitute nahi.','The system learns from supplied values. A target cannot substitute for the business model.')},
{id:'budget',title:P('12 · Budget aur loss limit','12 · Budget and loss limit'),where:'Campaign → Average daily budget',source:['budget'],
do:P('Average daily budget ko hard daily cap mat samjho. Most standard campaigns mein daily spend 2× tak aur unchanged full-month spending limit 30.4× average daily budget hoti hai; exceptions aur budget edits inspect karo. CPC/CVR forecast assumptions hain. Affordable test budget, sales delay aur stop conditions record karo.','Average daily budget is not a hard daily cap. For most standard campaigns, daily spend can reach 2× and an unchanged full-month spending limit is 30.4× the average daily budget; check exceptions and budget changes. Forecast CPC/CVR are assumptions. Record an affordable test budget, sales delay and stop conditions.'),
trap:P('Rs 1,000 average daily budget se har din exactly Rs 1,000 spend assume karna.','Assuming a Rs 1,000 average daily budget spends exactly Rs 1,000 every day.'),output:P('Monthly allowance, average daily budget, test loss limit aur review trigger likho.','Write the monthly allowance, average daily budget, test loss limit and review trigger.'),q:P('Unchanged full-month average daily budget Rs 1,000 hai. Standard planning limit kya hai?','The unchanged full-month average daily budget is Rs 1,000. What is the standard planning limit?'),options:[P('Rs 30,400, exceptions aur budget changes verify karte hue','Rs 30,400, checking exceptions and budget changes'),P('Har month exactly Rs 31,000','Exactly Rs 31,000 every month'),P('Har din Rs 1,000 ka hard cap','A hard cap of Rs 1,000 each day')],answer:0,why:P('1,000 × 30.4 = 30,400. Ye spend guarantee ya har possible billing scenario ki total invoice nahi.','1,000 × 30.4 = 30,400. This is not guaranteed spend or the total invoice for every billing scenario.'),practice:'calculator'},
{id:'review',title:P('13 · Publish se pehle review','13 · Review before publishing'),where:'Review → resolve issues → human launch decision',source:['setup','tagtest'],
do:P('Goal/action, networks, geo, language, audience, hours, budget/targets, keywords/negatives, RSA/assets, final URL, real conversion tests aur account/policy/billing status verify karo. Start/end dates aur customer capacity check karo. Recommendation ya optimization score ko mandatory business instruction mat samjho. Approval ke baad bhi serving/results guaranteed nahi.','Verify goals/actions, networks, geography, language, audiences, hours, budget/targets, keywords/negatives, RSA/assets, destination, real conversion tests and account/policy/billing status. Check dates and customer capacity. Recommendations or scores do not replace business judgment. Approval does not guarantee serving or results.'),
trap:P('Practice complete honay ko real account launch approval samajhna.','Treating completed practice as approval to launch a real account.'),output:P('Har blocker, owner, fix aur verification evidence ka launch checklist banao.','Create a launch checklist with each blocker, owner, fix and verification evidence.'),q:P('Tracking abhi test nahi hui aur budget owner ne approve nahi kiya.','Tracking is untested and the budget owner has not approved spending.'),options:[P('Practice score dekh kar launch kar do','Launch because the practice score looks good'),P('Missing evidence resolve karo aur authorized person se actual launch decision lo','Resolve missing evidence and let the authorized person decide the real launch'),P('Har recommendation blindly apply karo','Apply every recommendation blindly')],answer:1,why:P('Ye app simulated learning hai. Iska completion real account ki tracking, policy status ya financial authorization verify nahi karta.','This app is simulated learning. Completion does not verify real account tracking, policy status or spending authorization.'),practice:'checklist'},
{id:'week',title:P('14 · Pehla review aur next test','14 · First review and next test'),where:'Reports / Search terms / CRM / Change history',source:['terms','window','experiment'],screen:4,
do:P('Start par serving, broken page, spend anomalies aur measurement faults monitor karo. Performance decision conversion delay aur enough evidence ke baad karo; sab ke liye fixed 7-day rule nahi. Mature dates compare karo, relevant search terms dekho, CRM lead quality/cost inspect karo aur ek hypothesis test karo. Change log aur rollback condition likho.','Monitor serving, page failures, spend anomalies and measurement faults early. Make performance decisions after accounting for conversion delay and sufficient evidence; there is no fixed seven-day rule for every business. Compare mature periods, inspect search terms and CRM quality/cost, then test one hypothesis. Record a change log and rollback condition.'),
trap:P('3 clicks aur zero sales par roz bidding, ads aur page sab change karna.','Changing bidding, ads and pages every day after three clicks and no sales.'),output:P('Review dates, lag assumption, 3 metrics, ek hypothesis, success rule aur rollback likho.','Write review dates, lag assumption, three metrics, one hypothesis, success rule and rollback.'),q:P('Recent B2B leads close honay mein 30 din lete hain. Kal ke leads par sales zero hain.','B2B leads take 30 days to close. Yesterday’s leads show zero sales.'),options:[P('Campaign ko proved failure declare karo','Declare proven failure'),P('Sab leads ko sales count kar do','Count every lead as a sale'),P('Mature cohorts, qualified pipeline aur measurement check karo; sales abhi incomplete hain','Review mature cohorts, qualified pipeline and measurement; sales are incomplete')],answer:2,why:P('Incomplete outcomes aur real failure ko alag karo. Urgent faults ko turant fix karo, lekin performance inference lag aur uncertainty ke saath lo.','Separate incomplete outcomes from failure. Fix urgent faults promptly and account for lag and uncertainty in performance judgments.')}
];
const SETUP_EXAMPLES={
ac:[P('Lahore mein AC repair ki qualified booking. Raw enquiries ko verified area, repair need aur reachable contact se qualify karo.','A qualified AC repair booking in Lahore: verify the area, repair need and reachable contact.'),P('successful_booking_request → qualified_booking in CRM. Failed submission is not a lead.','successful_booking_request → qualified_booking in CRM. Failed submission is not a lead.'),P('Rs 8,000 job × 40% contribution = Rs 3,200/customer. 25% raw-lead close rate assumed.','Rs 8,000 job × 40% contribution = Rs 3,200/customer. Assume a 25% raw-lead close rate.'),P('CoolCare | Lahore | Repair | Non-brand · Leads → Search → reviewed booking goal.','CoolCare | Lahore | Repair | Non-brand · Leads → Search → reviewed booking goal.'),P('Lahore coverage only; staffed calls 09:00–18:00 Asia/Karachi; investigate out-of-area leads.','Lahore coverage only; staffed calls 09:00–18:00 Asia/Karachi; investigate out-of-area leads.'),P('Repair → /ac-repair; Installation → /ac-installation. Dono offers ko sahi page mile.','Repair → /ac-repair; Installation → /ac-installation. Match each offer to its page.'),P('[ac repair lahore], "ac technician lahore". Real customer searches se relevance verify karo.','[ac repair lahore], "ac technician lahore". Verify relevance through real customer searches.'),P('jobs aur technician course candidates hain. "service" ko negative bananay se useful repairs block ho sakti hain.','jobs and technician course are candidates. A service negative could block useful repair demand.'),P('AC Repair in Lahore | Book a Technician | Check Area Availability. Availability ka claim pehle confirm karo.','AC Repair in Lahore | Book a Technician | Check Area Availability. Confirm availability before claiming it.'),P('Repair page par service area, fees ka context, appointment request aur working phone/form.','Repair page: service area, fee context, appointment request and working phone/form.'),P('Booking-count objective ko qualified outcome se reconcile karo; arbitrary low CPA target mat lagao.','Reconcile booking-count optimization with qualified outcomes; avoid arbitrary low CPA targets.'),P('Rs 30,400 illustrative monthly allowance → Rs 1,000 average/day. Isay affordable honay ki proof mat samjho.','Illustrative Rs 30,400/month → Rs 1,000 average/day. This does not establish affordability.'),P('Technician capacity, call answering, verified success tag aur Lahore coverage evidence.','Evidence: technician capacity, call answering, verified success tag and Lahore coverage.'),P('Raw lead cost ke saath qualified booking cost aur completed-job contribution compare karo.','Compare raw lead cost, qualified booking cost and contribution from completed jobs.')],
shop:[P('Paid running-shoe orders. Cancelled/refunded orders aur delivery cost ko business reporting mein include karo.','Paid running-shoe orders. Include cancellations/refunds and delivery costs in business reporting.'),P('Purchase fires after confirmed success with value, currency and transaction ID. Test refresh/repeat.','Purchase fires after confirmed success with value, currency and transaction ID. Test refresh/repeat.'),P('Rs 6,500 order × 35% contribution = Rs 2,275/order, before fixed overhead.','Rs 6,500 order × 35% contribution = Rs 2,275/order, before fixed overhead.'),P('Stride | PK | Running Shoes | Non-brand · Sales → Search → reviewed purchase goal.','Stride | PK | Running Shoes | Non-brand · Sales → Search → reviewed purchase goal.'),P('Sirf deliverable areas; website ki language aur delivery/returns capability clear ho.','Only deliverable areas; align website language and delivery/returns capability.'),P('Running shoes → running collection; walking shoes → walking collection. Stock/size relevance dekho.','Running shoes → running collection; walking shoes → walking collection. Check stock and size relevance.'),P('[buy running shoes pakistan], "running shoes online". Brand searches alag identify karo.','[buy running shoes pakistan], "running shoes online". Identify brand searches separately.'),P('Repair training irrelevant; free delivery useful ho sakti hai. "free" blanket negative ka conflict test karo.','Repair training is irrelevant; free delivery may be useful. Test conflicts before adding a blanket free negative.'),P('Shop Running Shoes | Find Your Size Online | See Delivery Options. Har line factual ho.','Shop Running Shoes | Find Your Size Online | See Delivery Options. Keep every line factual.'),P('Correct collection/product, in-stock sizes, actual price, delivery/returns aur functioning mobile checkout.','Correct collection/product, available sizes, actual price, delivery/returns and a working mobile checkout.'),P('Order values aur currency accurate hon; gross revenue ROAS ko contribution profit se alag dekho.','Ensure accurate order values/currency; distinguish revenue ROAS from contribution profit.'),P('Rs 30,400 planning example: actual test allowance owner affordability aur inventory se decide ho.','Rs 30,400 planning example: decide actual allowance using affordability and inventory.'),P('Checkout, paid-order signal, transaction IDs, inventory, returns terms aur budget authorization.','Checkout, paid-order signal, transaction IDs, inventory, returns terms and budget authorization.'),P('Ads order totals ko paid net orders se reconcile karo. Refund delay aur margins ke baad contribution dekho.','Reconcile Ads totals with paid net orders. Evaluate contribution after refunds and margins.')],
b2b:[P('Karachi businesses ke qualified accounting opportunities; students/jobs enquiries useful sales leads nahi.','Qualified accounting opportunities from Karachi businesses; student/job enquiries are not sales opportunities.'),P('Consultation request → qualified opportunity → won client in CRM. Stages ko separately record karo.','Consultation request → qualified opportunity → won client in CRM. Record stages separately.'),P('Rs 40,000 initial sale × 50% contribution = Rs 20,000/client. 10% lead-to-client rate assumed.','Rs 40,000 initial sale × 50% contribution = Rs 20,000/client. Assume a 10% lead-to-client rate.'),P('LedgerPro | Karachi | Accounting | Non-brand · Leads → Search → reviewed consultation goal.','LedgerPro | Karachi | Accounting | Non-brand · Leads → Search → reviewed consultation goal.'),P('Defined business coverage, language capability, staffed consultation hours aur audience reach review.','Review business coverage, language capability, staffed consultation hours and audience reach.'),P('Bookkeeping → /bookkeeping; payroll → /payroll. Offer aur qualification context consistent rakho.','Bookkeeping → /bookkeeping; payroll → /payroll. Keep the offer and qualification context consistent.'),P('[accounting services karachi], "bookkeeping for businesses". Employment intent ko identify karo.','[accounting services karachi], "bookkeeping for businesses". Identify employment intent.'),P('accounting jobs / internship candidates; "business accounting" ko accidentally negative mat karo.','accounting jobs / internship are candidates; do not accidentally exclude business accounting.'),P('Accounting for Businesses | Discuss Your Bookkeeping | Request a Consultation. Unsupported savings avoid karo.','Accounting for Businesses | Discuss Your Bookkeeping | Request a Consultation. Avoid unsupported savings claims.'),P('Service scope, who it suits, consultation process, business trust details aur tested request form.','Service scope, suitable businesses, consultation process, trust details and a tested request form.'),P('Cheap raw leads se zyada qualification/won value dekho. Offline feedback ka implementation separately verify karo.','Consider qualification/won value beyond cheap raw leads. Verify offline feedback implementation separately.'),P('Long sales cycle mein loss limit aur cash-flow patience define karo. Budget se guaranteed customers nahi milte.','Define a loss limit and cash-flow runway for the long sales cycle. Budget does not guarantee clients.'),P('CRM stages, qualification owner, conversion lag aur actual spending authority verify karo.','Verify CRM stages, qualification ownership, conversion lag and actual spending authority.'),P('30-day sales delay assumed: mature cohorts aur qualified pipeline dekho, kal ki zero sales par final verdict nahi.','Assume a 30-day sales delay: inspect mature cohorts and qualified pipeline before judging yesterday’s zero sales.')]
};
function cleanJourney(value){const result={};if(!value||typeof value!=='object')return result;for(const b of BUSINESSES){const r=value[b.id];if(!r||typeof r!=='object')continue;const out={step:Number.isInteger(r.step)?Math.max(0,Math.min(SETUP_STEPS.length-1,r.step)):0,answers:{},notes:{},math:typeof r.math==='string'?r.math.slice(0,50):''};for(let i=0;i<SETUP_STEPS.length;i++){if(Number.isInteger(r.answers?.[i])&&r.answers[i]>=0&&r.answers[i]<SETUP_STEPS[i].options.length)out.answers[i]=r.answers[i];if(typeof r.notes?.[i]==='string')out.notes[i]=r.notes[i].slice(0,5000);}result[b.id]=out;}return result;}
function journeyRecord(){return state.journey[state.business]||(state.journey[state.business]={step:0,answers:{},notes:{},math:''});}
function journeyLimit(b=biz()){return b.aov*b.margin/100*b.close/100;}
function journeyMathOK(r=journeyRecord()){return checkMath({answer:journeyLimit()},r.math||'').correct;}
function journeyStepOK(i,r=journeyRecord()){return r.answers[i]===SETUP_STEPS[i].answer&&Boolean(r.notes[i]?.trim())&&(i!==2||journeyMathOK(r));}
function journeySolved(b=state.business){const r=state.journey[b];return r?SETUP_STEPS.filter((s,i)=>r.answers[i]===s.answer&&r.notes[i]?.trim()&&(i!==2||checkMath({answer:journeyLimit(BUSINESSES.find(x=>x.id===b))},r.math||'').correct)).length:0;}
function journeyPage(){const r=journeyRecord(),i=r.step,s=SETUP_STEPS[i],selected=r.answers[i],b=biz();return `${heading('SEARCH CAMPAIGN · START TO FIRST REVIEW',U('Ek campaign. Har decision ki practice.','One campaign. Practise each decision.'),U('14 steps: samjho, faisla karo aur apna plan likho. Progress har business ke liye alag save hoti hai.','14 steps: understand, decide and write your plan. Progress saves separately for each business.'))}<div class="note">${U('Teaching walkthrough · Google UI ka clone ya live account nahi. Sirf explicitly labelled images original screenshots hain. Ye steps planning order hain; actual account flow change ho sakta hai.','Teaching walkthrough · not a Google UI clone or live account. Only explicitly labelled images are original screenshots. These steps follow a planning order; actual account flows may differ.')}</div><div class="section-heading" style="margin-top:22px"><span class="tag">${journeySolved()} / ${SETUP_STEPS.length} ${U('practice steps complete','practice steps complete')}</span><select class="lang" id="journey-business" aria-label="Walkthrough business">${BUSINESSES.map(x=>`<option value="${x.id}" ${x.id===state.business?'selected':''}>${esc(t(x.name))}</option>`).join('')}</select></div><div class="journey-layout"><aside class="card journey-menu">${SETUP_STEPS.map((x,n)=>`<button class="guide-step ${i===n?'active':''}" data-journey-step="${n}" aria-current="${i===n?'step':'false'}"><span>${journeyStepOK(n)?'✓':'○'}</span>${esc(t(x.title))}</button>`).join('')}</aside><article class="card"><div class="eyebrow">STEP ${i+1} / ${SETUP_STEPS.length} · ${esc(s.where)}</div><h2>${esc(t(s.title).slice(5))}</h2><p class="guide-instruction">${esc(t(s.do))}</p><div class="example"><div class="label">${esc(t(b.name))} · FICTIONAL EXAMPLE</div><p>${esc(t(SETUP_EXAMPLES[b.id][i]))}</p></div><details class="source-details"><summary>${U('Aam galti aur official instructions','Common mistake and official instructions')}</summary><p>${esc(t(s.trap))}</p>${sourceLinks(s.source)}</details>${s.screen!==undefined?`<details class="source-details"><summary>${U('Related original Google Ads screenshot','Related original Google Ads screenshot')}</summary><img class="journey-capture" src="assets/google-ads/${REAL_SCREENS[s.screen].file}" alt="${esc(t(REAL_SCREENS[s.screen].title))} · original cropped Google Ads UI"><p>© Google · Original UI crop · Captured 20 Oct 2026</p><button class="text-btn" id="journey-screen">${U('Clickable explanation kholo','Open clickable explanation')} →</button></details>`:''}<section class="quiz"><div class="eyebrow">${U('PEHLE FAISLA KARO','MAKE THE DECISION')}</div><h3>${esc(t(s.q))}</h3><div class="quiz-options">${s.options.map((o,n)=>`<button class="option ${selected===n?(n===s.answer?'correct':'wrong'):''}" data-journey-answer="${n}">${String.fromCharCode(65+n)}. ${esc(t(o))}</button>`).join('')}</div>${selected!==undefined?`<div class="feedback ${selected===s.answer?'':'error'}" role="status">${selected===s.answer?'✓':U('Dobara socho.','Try again.')} ${esc(t(s.why))}</div>`:''}</section>${i===2?journeyEconomics():''}${i===10?journeyBiddingUpdate():''}<label class="field" style="margin-top:25px"><b>${U('Ab apna output likho','Now write your output')}</b><span>${esc(t(s.output))}</span><textarea id="journey-note" maxlength="5000" rows="5" placeholder="${U('Sirf fictional practice data. Real client details mat likho.','Fictional practice data only. Do not enter private client details.')}">${esc(r.notes[i]||'')}</textarea></label><p class="screen-credit" id="journey-save" role="status">${U('Output autosave hota hai. Text ka business correctness app verify nahi karti.','Output saves automatically. The app cannot verify the business correctness of your writing.')}</p><div class="action-row">${s.practice?`<button class="btn light" id="journey-practice">${U('Related exercise kholo','Open related exercise')} →</button>`:''}<button class="btn light" data-go="guides">${U('Implementation workbook','Implementation workbook')}</button></div><div class="lesson-nav"><button class="btn light" id="journey-prev" ${!i?'disabled':''}>← ${U('Pichla step','Previous step')}</button><button class="btn" id="journey-next">${i===SETUP_STEPS.length-1?U('Plan review kholo','Open plan review'):U('Agla step','Next step')} →</button></div><div id="journey-feedback" aria-live="polite"></div></article></div><section class="card" style="margin-top:22px" id="journey-review"><h2>${U('Tumhara connected setup plan','Your connected setup plan')}</h2><p>${U('Correct decisions + written outputs + economics check se practice complete hoti hai. Real launch authorization ya live tracking validation nahi.','Practice completion requires correct decisions, written outputs and the economics check. This is not real launch authorization or live tracking validation.')}</p><div class="progress-track"><div class="progress-fill" style="width:${journeySolved()/SETUP_STEPS.length*100}%"></div></div><div class="journey-summary">${SETUP_STEPS.map((x,n)=>`<details><summary>${journeyStepOK(n)?'✓':'○'} ${esc(t(x.title))}</summary><p class="preserve-text">${esc(r.notes[n]||U('Output abhi likhna hai.','Output not yet written.'))}</p><button class="text-btn" data-journey-step="${n}">${U('Step review karo','Review step')} →</button></details>`).join('')}</div><div class="action-row"><button class="btn light" id="journey-export">${U('Plan download karo','Download plan')}</button><button class="btn" id="journey-draft">${U('Campaign draft editor kholo','Open campaign draft editor')} →</button></div></section>${footer()}`;}
function journeyEconomics(){const b=biz(),r=journeyRecord(),ok=journeyMathOK(r);return `<section class="campaign-section"><h3>${U('Khud calculate karo','Calculate it yourself')}</h3><p>${U('Fictional inputs; benchmarks nahi. Is model mein margin variable costs ke baad hai.','Fictional inputs, not benchmarks. In this model margin is after variable costs.')}</p><div class="metrics">${metric('Sale / order value',money(b.aov),'Fictional assumption')}${metric('Contribution margin',b.margin+'%','Before ads & fixed overhead')}${metric('Lead → customer',b.close+'%','Shop: paid order is already a sale')}</div><label class="field">${U('Break-even cost per raw lead/order (Rs)','Break-even cost per raw lead/order (Rs)')}<input id="journey-math" type="text" inputmode="decimal" value="${esc(r.math)}" autocomplete="off"></label><button class="btn light" id="journey-math-check">${U('Answer check karo','Check answer')}</button><div id="journey-math-feedback" aria-live="polite">${r.math?`<div class="feedback ${ok?'':'error'}">${ok?U('Sahi. Ye break-even hai; profitable target nahi.','Correct. This is break-even, not a profitable target.'):U('Abhi match nahi. Hint kholo aur dobara try karo.','Not matched yet. Open the hint and try again.')}</div>`:''}</div><details class="source-details"><summary>${U('Hint aur worked solution','Hint and worked solution')}</summary><div class="formula">${b.aov} × ${b.margin}/100 × ${b.close}/100 = ${num(journeyLimit(),2)} Rs</div><p>${U('Fixed overhead, refunds, sales costs aur profit reserve se actual affordable target aur kam ho sakta hai.','Fixed overhead, refunds, sales costs and a profit reserve can lower the affordable target further.')}</p></details></section>`;}
function setJourneyStep(i){journeyRecord().step=Math.max(0,Math.min(SETUP_STEPS.length-1,i));save();render();}
function journeyExport(){const r=journeyRecord();return{schema:1,simulation:true,business:biz().name[1],sourceReview:'2026-10-20',exportedAt:new Date().toISOString(),practiceStepsComplete:journeySolved(),totalSteps:SETUP_STEPS.length,math:{answer:r.math,correct:journeyMathOK(),assumptions:{orderValue:biz().aov,contributionMarginPercent:biz().margin,leadToCustomerPercent:biz().close}},steps:SETUP_STEPS.map((s,i)=>({step:s.id,title:s.title[1],output:r.notes[i]||'',decisionCorrect:r.answers[i]===s.answer,practiceComplete:journeyStepOK(i),sources:s.source.map(k=>'https://support.google.com/google-ads/answer/'+SOURCES[k][1]+'?hl=en')})),notice:'Fictional learning plan. Does not verify a real account or authorize spending.'};}
function bindJourney(){const r=journeyRecord(),i=r.step,s=SETUP_STEPS[i];$('#journey-business').onchange=e=>{state.business=e.target.value;save();render();};$$('[data-journey-step]').forEach(b=>b.onclick=()=>setJourneyStep(+b.dataset.journeyStep));$$('[data-journey-answer]').forEach(b=>b.onclick=()=>{r.answers[i]=+b.dataset.journeyAnswer;save();const y=window.scrollY;render();window.scrollTo(0,y);});$('#journey-note').oninput=e=>{r.notes[i]=e.target.value.slice(0,5000);save();$('#journey-save').textContent=storageOK?U('Output saved. Agla step dabao ya plan review karo.','Output saved. Continue or review the plan.'):U('Storage unavailable. Plan download karke save karo.','Storage unavailable. Download the plan to save it.');};const math=$('#journey-math');if(math){math.oninput=e=>{r.math=e.target.value.slice(0,50);save();};$('#journey-math-check').onclick=()=>{const y=window.scrollY;render();window.scrollTo(0,y);};}$('#journey-prev').onclick=()=>setJourneyStep(i-1);$('#journey-next').onclick=()=>{if(!journeyStepOK(i)){$('#journey-feedback').innerHTML=`<div class="feedback error">${U('Pehle sahi decision choose karo, output likho aur economics step par calculation solve karo.','Choose the correct decision, write your output and solve the calculation on the economics step first.')}</div>`;return;}if(i<SETUP_STEPS.length-1)setJourneyStep(i+1);else{render();$('#journey-review').scrollIntoView({behavior:'smooth'});}};$('#journey-export').onclick=()=>download('ads-asaan-'+state.business+'-setup-plan.json',journeyExport());$('#journey-draft').onclick=()=>{labTab='campaign';go('lab');};const screen=$('#journey-screen');if(screen)screen.onclick=()=>{screenIndex=s.screen;screenPin=0;go('screens');};const practice=$('#journey-practice');if(practice)practice.onclick=()=>{if(s.practice==='tracking'){clinicTab='tracking';go('clinic');}else if(s.practice==='calculator')go('calculators');else{labTab=s.practice==='checklist'?'campaign':s.practice;go('lab');}};}

function journeyBiddingUpdate(){return `<section class="campaign-section"><div class="eyebrow">CURRENT PRIORITY · GOOGLE UPDATES · 2026</div><h3>${U('Purani video se labels different kyun hain?','Why do older videos show different labels?')}</h3><p>${U('June 2026 se Target CPA aur Target ROAS standalone labels mein aa rahay hain. Transition mein purana bundled naam bhi nazar aa sakta hai. Sirf label change ko nayi performance guarantee mat samjho.','Since June 2026, Target CPA and Target ROAS are moving to standalone labels. Older bundled names can still appear during the transition. A label change is not a performance guarantee.')}</p><h3>${U('Target ko seriously review karo','Review the stated target carefully')}</h3><p>${U('17 August 2026 ke update mein budget-limited target-based campaigns stated target ke qareeb optimize karti hain. Example: target CPA Rs 1,200 aur mature actual Rs 700 ho to Rs 700 hamesha rehne ki assumption mat karo. Affordable economics aur business goal se target review karo; target har conversion ka hard cost cap nahi. Is app mein koi live target change nahi hota.','The 17 August 2026 update makes budget-limited target-based campaigns optimize more closely toward the stated target. If target CPA is Rs 1,200 while mature actual CPA is Rs 700, do not assume Rs 700 will persist. Review the target against affordability and business goals; it is not a hard cost cap per conversion. This app changes no live targets.')}</p>${sourceLinks(['bidlabels','bidtargets'])}<small>Verified against Google documentation · 20 Oct 2026</small></section>`;}
